<?php
/** @var string $base @var string $csrf @var array $ticket @var array $messages @var array $statuses */
$e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$categoryLabels = ['technical'=>'Teknis','billing'=>'Billing / pembayaran','account'=>'Akun','other'=>'Lainnya'];
?>
<div class="mb-3"><a class="small text-decoration-none" href="<?= $e($base) ?>/owner/support">← Kembali ke tiket</a></div>
<div class="row g-3">
  <section class="col-xl-8"><div class="card"><div class="card-header d-flex justify-content-between align-items-start gap-3"><div><h2 class="h5 mb-1"><?= $e($ticket['subject']) ?></h2><div class="small text-muted">#<?= $e($ticket['ticket_no']) ?> · <?= $e($categoryLabels[$ticket['category']] ?? $ticket['category']) ?> · <?= $e($ticket['tenant_name']) ?></div></div><span class="badge text-bg-<?= $ticket['status']==='resolved'?'success':($ticket['status']==='waiting_owner'?'warning':'primary') ?>"><?= $e($statuses[$ticket['status']] ?? $ticket['status']) ?></span></div>
    <div class="card-body"><div class="d-grid gap-3">
      <?php foreach ($messages as $message): $isOwner=$message['sender_role']==='owner'; ?>
        <article class="p-3 border rounded-2 <?= $isOwner?'bg-light':'' ?>"><div class="d-flex justify-content-between gap-2"><strong><?= $e($message['sender_name']) ?> <span class="small fw-normal text-muted">· <?= $isOwner?'Owner':'Admin' ?></span></strong><time class="small text-muted"><?= $e(date('d M Y, H:i',strtotime((string)$message['created_at']))) ?></time></div><div class="mt-2 text-break" style="white-space:pre-wrap"><?= $e($message['body']) ?></div></article>
      <?php endforeach; ?>
    </div></div>
    <?php if ($ticket['status'] !== 'resolved'): ?><form method="post" action="<?= $e($base) ?>/owner/support/reply" class="card-footer"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label class="form-label small fw-semibold" for="replyBody">Balas tiket</label><textarea class="form-control mb-2" id="replyBody" name="body" rows="4" minlength="2" maxlength="5000" required></textarea><button class="btn btn-primary btn-sm" type="submit">Kirim balasan</button></form><?php else: ?><div class="card-footer small text-muted">Tiket telah ditandai selesai. Kirim balasan baru untuk membukanya kembali.</div><form method="post" action="<?= $e($base) ?>/owner/support/reply" class="card-footer border-top-0"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label class="form-label small fw-semibold" for="replyBody">Buka kembali dengan balasan</label><textarea class="form-control mb-2" id="replyBody" name="body" rows="3" minlength="2" maxlength="5000" required></textarea><button class="btn btn-outline-primary btn-sm" type="submit">Kirim dan buka kembali</button></form><?php endif; ?>
  </div></section>
  <aside class="col-xl-4"><div class="card"><div class="card-header fw-semibold">Informasi tiket</div><dl class="card-body mb-0"><dt class="small text-muted">Status</dt><dd><?= $e($statuses[$ticket['status']] ?? $ticket['status']) ?></dd><dt class="small text-muted">Dibuat</dt><dd><?= $e(date('d M Y, H:i',strtotime((string)$ticket['created_at']))) ?></dd><dt class="small text-muted">Terakhir diperbarui</dt><dd><?= $e(date('d M Y, H:i',strtotime((string)$ticket['updated_at']))) ?></dd><?php if($ticket['invoice_no']): ?><dt class="small text-muted">Invoice terkait</dt><dd><a href="<?= $e($base) ?>/owner/billing/invoice?id=<?= (int)$ticket['invoice_id'] ?>"><?= $e($ticket['invoice_no']) ?></a></dd><?php endif; ?></dl></div></aside>
</div>